class SquareDataset(Dataset):
    def __init__(self, values):
        self.values = values

    def __len__(self):
        return len(self.values)

    def __getitem__(self, i):
        v = self.values[i]
        return torch.tensor(v), torch.tensor(v * v)


xb, yb = next(iter(DataLoader(SquareDataset(values), batch_size=batch)))
